PDF_STORAGE_DIR = "quotations"
def build_quotation_pdf_file(data: dict, file_path: str, company_logo_b64: str = None, second_logo_b64: str = None, stamp_b64: str = None):
    # 14mm Margins
    margin_pt = 14 * 2.83465
    companyLogoBase64 = 'data:image/png;base64,'
    secondLogoBase64 = 'data:image/png;base64,'
    stampBase64 ='data:image/png;base64,'

    
    doc = SimpleDocTemplate(
        file_path,
        pagesize=A4,
        leftMargin=margin_pt,
        rightMargin=margin_pt,
        topMargin=margin_pt,
        bottomMargin=margin_pt
    )

    story = []
    styles = getSampleStyleSheet()
    
    style_normal = ParagraphStyle('NormalText', parent=styles['Normal'], fontName='Helvetica', fontSize=9, leading=11, textColor=colors.HexColor('#646464'))
    style_bold_10 = ParagraphStyle('Bold10Text', parent=styles['Normal'], fontName='Helvetica-Bold', fontSize=10, leading=12, textColor=colors.HexColor('#323232'))
    style_normal_10 = ParagraphStyle('Normal10Text', parent=styles['Normal'], fontName='Helvetica', fontSize=10, leading=12, textColor=colors.HexColor('#323232'))
    
    style_title = ParagraphStyle('TitleText', parent=styles['Normal'], fontName='Helvetica-Bold', fontSize=10, leading=14, alignment=TA_CENTER, textColor=colors.HexColor('#323232'))
    style_right_bold = ParagraphStyle('RightBold', parent=styles['Normal'], fontName='Helvetica-Bold', fontSize=10, leading=12, alignment=TA_RIGHT, textColor=colors.HexColor('#1E1E1E'))
    style_right_italic = ParagraphStyle('RightItalic', parent=styles['Normal'], fontName='Helvetica-Oblique', fontSize=9, leading=11, alignment=TA_RIGHT, textColor=colors.HexColor('#323232'))

    def b64_to_image(b64_str, width_mm, height_mm):
        if not b64_str:
            return None
        try:
            if ',' in b64_str:
                b64_str = b64_str.split(',')[1]
            img_data = base64.b64decode(b64_str)
            return Image(BytesIO(img_data), width=width_mm * 2.83465, height=height_mm * 2.83465)
        except Exception:
            return None

    # 1. Convert millimeter dimensions to ReportLab points (1mm = 2.83465pt)
    logo1 = b64_to_image(companyLogoBase64, 17, 10)  # 17mm x 10mm
    logo2 = b64_to_image(secondLogoBase64, 26, 7)    # 26mm x 7mm

    logo_cells = []
    
    if logo1 or logo2:
        # Construct side-by-side table for the two logos
        logo_row = []
        col_widths = []
        
        if logo1:
            logo_row.append(logo1)
            col_widths.append(17 * 2.83465)  # 17mm width
        if logo2:
            logo_row.append(logo2)
            col_widths.append(26 * 2.83465)  # 26mm width

        # Create an inner table for side-by-side logos
        logos_table = Table([logo_row], colWidths=col_widths)
        logos_table.setStyle(TableStyle([
            ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),  # Align bottoms side-by-side
            ('LEFTPADDING', (0, 0), (-1, -1), 0),
            ('RIGHTPADDING', (0, 0), (-1, -1), 4),  # 4pt space between logo 1 and logo 2
            ('TOPPADDING', (0, 0), (-1, -1), 0),
            ('BOTTOMPADDING', (0, 0), (-1, -1), 0),
        ]))
        logo_cells = [logos_table]
    else:
        # Fallback text if no logos provided
        logo_cells = [Paragraph("<font size=18 color='#F4511E'><b>24 X 7 IT Services</b></font>", styles['Normal'])]

    header_table = Table([[logo_cells]], colWidths=[524.41])
    header_table.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'BOTTOM'),
        ('LEFTPADDING', (0, 0), (-1, -1), 0),
        ('RIGHTPADDING', (0, 0), (-1, -1), 0),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
    ]))
    story.append(header_table)

    story.append(Paragraph("Plot No 5459, Barihapur, Parjang, Dhenkanal-759120", style_normal))
    story.append(Paragraph("Email: Pabitra.itservices2023@gmail.com | Phone: 9178512248", style_normal))
    story.append(Paragraph("GSTN: 21CIDPM7240R1ZY", style_normal))
    story.append(Spacer(1, 4))

    # Orange Divider Line (#F4511E)
    divider = Table([['']], colWidths=[524.41], rowHeights=[2])
    divider.setStyle(TableStyle([
        ('LINEABOVE', (0, 0), (-1, -1), 1.5, colors.HexColor('#F4511E')),
        ('TOPPADDING', (0, 0), (-1, -1), 0),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 0),
    ]))
    story.append(divider)
    story.append(Spacer(1, 8))

    # Metadata Row: Ref No & Date
    meta_table = Table([[
        Paragraph(f"<b>Ref. No: {data.get('refNo', 'N/A')}</b>", style_normal_10),
        Paragraph(f"Date: {data.get('date', 'N/A')}", style_right_bold)
    ]], colWidths=[262.2, 262.2])
    meta_table.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('LEFTPADDING', (0, 0), (-1, -1), 0),
        ('RIGHTPADDING', (0, 0), (-1, -1), 0),
    ]))
    story.append(meta_table)
    story.append(Spacer(1, 10))

    # Client Info
    story.append(Paragraph("<b>To,</b>", style_bold_10))
    story.append(Paragraph(f"<b>{data.get('clientName', 'N/A')}</b>", style_bold_10))
    client_address = (data.get('clientAddress') or '').replace('\n', '<br/>')
    if client_address:
        story.append(Paragraph(client_address, style_normal_10))
    story.append(Spacer(1, 12))

    # Subheading
    story.append(Paragraph(f"Sub: Price Quotation For {data.get('quotation_for', 'N/A')}", style_title))
    story.append(Spacer(1, 8))
    story.append(Paragraph("<b>Dear Sir,</b>", style_bold_10))
    story.append(Paragraph("With due respect, we bring your kind attention that we are submitting our most competitive offer with our terms & conditions in below for your kind consideration.", style_normal_10))
    story.append(Spacer(1, 10))

    # --- ITEMS TABLE ---
    col_widths = [34.0, 187.0, 42.5, 42.5, 68.0, 68.0, 82.41]
    
    table_data = [
        [
            Paragraph("<b>SL.No</b>", style_title),
            Paragraph("<b>ITEM DESCRIPTION</b>", style_title),
            Paragraph("<b>QTY</b>", style_title),
            Paragraph("<b>UNIT</b>", style_title),
            Paragraph("<b>RATE</b>", style_title),
            Paragraph("<b>GST @ 18%</b>", style_title),
            Paragraph("<b>TOTAL AMOUNT</b>", style_title),
        ]
    ]

    items = data.get('items', [])
    for idx, item in enumerate(items, start=1):
        rate_str = f"{item.get('rate', 0.0):,.2f}"
        gst_str = f"{item.get('gst', 0.0):,.2f}"
        total_str = f"{item.get('total', 0.0):,.2f}"

        row = [
            Paragraph(str(idx), style_normal_10),
            Paragraph(item.get('itemDescription', ''), style_normal_10),
            Paragraph(str(item.get('qty', 1)), style_title),
            Paragraph(item.get('unit', 'Nos'), style_title),
            Paragraph(rate_str, style_right_bold),
            Paragraph(gst_str, style_right_bold),
            Paragraph(total_str, style_right_bold)
        ]
        table_data.append(row)

    items_table = Table(table_data, colWidths=col_widths, repeatRows=1)
    
    ts = [
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#F4511E')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('ALIGN', (0, 0), (-1, -1), 'LEFT'),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('TOPPADDING', (0, 0), (-1, -1), 5),
        ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#E0E0E0')),
    ]
    
    for i in range(1, len(table_data)):
        if i % 2 == 0:
            ts.append(('BACKGROUND', (0, i), (-1, i), colors.HexColor('#F9F9F9')))
            
    items_table.setStyle(TableStyle(ts))
    story.append(items_table)
    story.append(Spacer(1, 10))

    # --- FOOTER BLOCK ---
    footer_elements = []

    # Grand Total
    grand_total_val = f"{data.get('grandTotal', 0.0):,.2f}"
    gt_paragraph = Paragraph(f"<b>GRAND TOTAL (Inclusive of Tax): &nbsp;&nbsp; INR {grand_total_val}</b>", style_right_bold)
    footer_elements.append(gt_paragraph)
    footer_elements.append(Spacer(1, 12))

    # Terms (Left Column)
    terms_p = [
        Paragraph("<b>Terms & Conditions:</b>", style_bold_10),
        Paragraph("<font color='#505050'>1. GST 18% inclusive as per standard regulatory policy.</font>", style_normal),
        Paragraph("<font color='#505050'>2. Delivery within 5 business days post formal reception of purchase order confirmation.</font>", style_normal),
        Paragraph("<font color='#505050'>3. Warranty lifecycle coverage will be managed directly by parent company.</font>", style_normal),
        Paragraph("<font color='#505050'>4. This price quote validation structure holds active for exactly 30 days.</font>", style_normal)
    ]

    if data.get('additional_emi_option'):
        terms_p.append(Spacer(1, 6))
        terms_p.append(Paragraph(data.get('additional_emi_option'), style_normal_10))

    # Stamp & Sign (Right Column)
    stamp_img = b64_to_image(stampBase64, 45, 20)
    
    sign_p = [
        Paragraph("<b>For M/S 24 X 7 IT SERVICES</b>", style_right_bold),
        Spacer(1, 4),
        stamp_img if stamp_img else Spacer(1, 20),
        Spacer(1, 4),
        Paragraph("Authorized Signatory (Proprietor)", style_right_italic)
    ]

    bottom_table = Table([[terms_p, sign_p]], colWidths=[310.0, 214.41])
    bottom_table.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('LEFTPADDING', (0, 0), (-1, -1), 0),
        ('RIGHTPADDING', (0, 0), (-1, -1), 0),
    ]))

    footer_elements.append(bottom_table)

    story.append(KeepTogether(footer_elements))
    doc.build(story)

@app.post("/api/admin/generatewhatsapplink/{ref_no:path}", tags=["whatsapp"])
def generate_whatsapp_quotation_pdf(ref_no: str, db: SessionDep):
    try:
        # 1. Fetch quotation and db_products from database
        quotation, db_products = crud.get_quotation_by_ref_number(session=db, ref_no=ref_no)
        if not quotation:
            raise HTTPException(
                status_code=status.HTTP_404_NOT_FOUND, 
                detail=f"Quotation with url_call '{ref_no}' was not found."
            )

        # 2. Format Items List
        items_list = []
        for p in db_products:
            items_list.append({
                "itemDescription": getattr(p, "product_name", ""),
                "unit": getattr(p, "unit", "Nos"),
                "qty": getattr(p, "quantity", 1),
                "rate": float(getattr(p, "price", 0.0) or 0.0),
                "gst": float(getattr(p, "gst", 0.0) or 0.0),
                "total": float(getattr(p, "total", 0.0) or 0.0)
            })

        # 3. Format Date Helper
        def format_date(val):
            if not val:
                return ""
            if hasattr(val, "strftime"):
                return val.strftime("%d/%m/%Y")
            if hasattr(val, "isoformat"):
                return val.isoformat()
            return str(val)

        # 4. Construct Data Structure for PDF Template
        pdf_data = {
            "refNo": getattr(quotation, "quotation_reference_number", ref_no),
            "date": format_date(getattr(quotation, "quotation_date", getattr(quotation, "created_at", None))),
            "clientName": getattr(quotation, "client_employee_id", "N/A"),
            "clientAddress": getattr(quotation, "client_address", getattr(quotation, "address", "")),
            "quotation_for": getattr(quotation, "quotation_for", "N/A"),
            "additional_emi_option": getattr(quotation, "additional_offer", None),
            "grandTotal": float(getattr(quotation, "total_amount", 0.0) or 0.0),
            "items": items_list
        }

        # 5. Output PDF File Path Setup
        safe_filename = f"Quotation_{ref_no.replace('/', '_')}.pdf"
        os.makedirs(PDF_STORAGE_DIR, exist_ok=True)
        file_path = os.path.join(PDF_STORAGE_DIR, safe_filename)

        # 6. Build PDF File
        build_quotation_pdf_file(
            data=pdf_data, 
            file_path=file_path,
            company_logo_b64=getattr(quotation, "logo_b64", None),
            stamp_b64=getattr(quotation, "stamp_b64", None)
        )

        # 7. Construct Public PDF Download URL
        public_pdf_url = f"{settings.BASE_URL}/{PDF_STORAGE_DIR}/{safe_filename}"

        # 8. Prepare and Encrypt Response
        response_payload = {
            "success": True,
            "pdf_url": public_pdf_url,
            "ref_no": ref_no,
            "client_phone": getattr(quotation, "phone", getattr(quotation, "client_phone", "")),
        }

        encrypted_data = security.encrypt_form_data(response_payload)
        if not encrypted_data:
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail="Outbound encryption failed."
            )

        return {
            "status": 200,
            "message": "PDF generated and stored successfully",
            "data": encrypted_data,
        }

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, 
            detail=str(e)
        )

